"""Fixed, labeled unanswerable query set. Commit this file before running improvement."""
import json
from pathlib import Path
from .data import assign_split

# Queries intentionally target information that commonly may not exist in a given agreement.
# Validate against the indexed contract set before use; do not edit after committing.
QUERIES = [
"Does this agreement permit sublicensing to a competitor's streaming platform?",
"What is the exact time of day when the exclusivity period expires?",
"Does the agreement require 4K HDR delivery for every episode?",
"Which party owns a new machine-learning model trained on the licensed content?",
"Does the contract grant rights to create virtual-reality adaptations?",
"What is the contractual penalty for a breach of a 48-hour delivery deadline?",
"Does the agreement permit use of the content in political advertisements?",
"What is the named contact's personal mobile number?",
"Does the contract require a carbon-neutral production process?",
"Can the licensee distribute the content on an in-flight entertainment system?",
"Does the agreement include a minimum guaranteed audience size?",
"What is the exact exchange rate to be used for royalty conversion?",
"Does the contract require the licensor to provide source code?",
"Can the content be used to train a generative AI model?",
"Does the agreement allow distribution through a blockchain platform?",
"What is the service-level uptime guarantee for the streaming service?",
"Does the contract require sign language interpretation for all episodes?",
"Which party pays for cyber insurance following a data breach?",
"Does the agreement set a maximum bitrate for promotional clips?",
"Can the licensee create merchandise based on characters in the show?",
"Does the contract require a third-party security audit every quarter?",
"What is the agreed penalty interest rate for late royalty payments?",
"Does the agreement grant rights for holographic performances?",
"Can the licensee sublicense rights to an airline?",
"Does the contract require deletion of all backups within 12 hours?",
"Does the agreement specify a mandatory cloud hosting provider?",
"Who owns audience analytics generated by an external ad-tech vendor?",
"Does the contract include a right to audit subcontractors' source code?",
"Can the licensee use the content in an interactive game?",
"Does the agreement guarantee a minimum number of social-media impressions?",
"Does the agreement require all production staff to hold a particular certification?",
"Does the contract allow sublicensing to a cryptocurrency exchange?",
"Does the contract require a particular encryption algorithm for stored files?",
"Does the agreement provide a guaranteed response time for technical support?",
"Can the licensee make translated audio descriptions for the licensed content?",
]

def write_fixed_set(path="data/unanswerable_queries.json"):
    rows = [{"id": f"unans-{i+1:03d}", "query": q, "answerable": False,
             "split": assign_split(q)} for i, q in enumerate(QUERIES)]
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    Path(path).write_text(json.dumps(rows, indent=2), encoding="utf-8")
    return rows

if __name__ == "__main__":
    rows = write_fixed_set()
    print("Wrote", len(rows), "queries; split counts:",
          {s: sum(x["split"] == s for x in rows) for s in ("train", "test")})
